import{_ as s,C as d,o as i,c as n,j as a,a as r,E as o,a2 as c}from"./chunks/framework.BxGh02fV.js";const _=JSON.parse('{"title":"Frame work with OPALE","description":"","frontmatter":{"title":"Frame work with OPALE"},"headers":[],"relativePath":"en/agent/cadrer.md","filePath":"en/agent/cadrer.md"}'),l={name:"en/agent/cadrer.md"};function h(f,e,p,u,m,g){const t=d("Ask");return i(),n("div",null,[e[0]||(e[0]=a("h1",{id:"frame-work-with-opale",tabindex:"-1"},[r("Frame work with OPALE "),a("a",{class:"header-anchor",href:"#frame-work-with-opale","aria-label":'Permalink to "Frame work with OPALE"'},"​")],-1)),e[1]||(e[1]=a("p",null,"An OPALE story is prepared before it is coded: analysis, framing, specifications, plan, then execution. You come here when you want to set out the problem with your agent, record decisions and questions, or, on the contrary, fix a defect without ceremony.",-1)),e[2]||(e[2]=a("h2",{id:"what-you-ask-the-agent",tabindex:"-1"},[r("What you ask the agent "),a("a",{class:"header-anchor",href:"#what-you-ask-the-agent","aria-label":'Permalink to "What you ask the agent"'},"​")],-1)),o(t,{say:"Create the framing documents for story 003 of epic 012.",verb:"effortless_cadrage_docs_scaffold",family:"cadrage",args:'{"epic_id":"012","story_id":"003"}'}),o(t,{say:'Record, on story 003 of epic 012, the decision "Export as CSV" in the framing phase, because Excel must open the exports; consequence: handle the encoding; ruled-out alternative: JSON.',verb:"effortless_decision_add",family:"cadrage",args:'{"epic_id":"012","story_id":"003","title":"Export as CSV","context":"Excel must open the exports","decision":"Export as CSV","consequences":"Handle the encoding","rejected_alternatives":"JSON","phase":"P-cadrage"}'}),o(t,{say:"On story 003 of epic 012, ask the authentication question in the framing phase: context, the application will be multi-user; impact, nothing moves forward without an answer; suggestion, OAuth2.",verb:"effortless_question_ask",family:"cadrage",args:'{"epic_id":"012","story_id":"003","question":"Which authentication?","context":"The application will be multi-user","impact":"Nothing moves forward without an answer","suggestion":"OAuth2","phase":"P-cadrage"}'}),o(t,{say:"Can we move to the next phase?",verb:"effortless_phase_eligibility",family:"cycle-de-vie"}),o(t,{say:"List the project's decisions and open questions.",verb:"effortless_decisions_list",family:"cadrage"}),o(t,{say:"Suggest three stories to break this epic down: CSV export, Excel export, archiving. I will validate them.",verb:"effortless_draft_add",family:"cadrage",args:'{"title":"CSV export"}'}),o(t,{say:'It is a small fix, "Fix the accent in the export": open a direct fix story, without framing.',verb:"effortless_story_start",family:"cycle-de-vie",args:'{"title":"Fix the accent in the export","kind":"fix"}'}),o(t,{say:"Which acceptance scenarios are still to be verified?",verb:"effortless_recipe_maturity",family:"cadrage"}),e[3]||(e[3]=c('<h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><h3 id="prepare-a-story-s-documents" tabindex="-1">Prepare a story&#39;s documents <a class="header-anchor" href="#prepare-a-story-s-documents" aria-label="Permalink to &quot;Prepare a story&#39;s documents&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/cadrage.html#cadrage-docs-scaffold"><code>effortless_cadrage_docs_scaffold</code></a> with <code>epic_id</code> and <code>story_id</code>: creates the story&#39;s missing OPALE documents in <code>blueprints/</code> and returns the files created. Documents already there are left alone.</li><li><a href="/Effortless/en/reference/mcp/cadrage.html#cadrage-layer-next"><code>effortless_cadrage_layer_next</code></a>: at project level, tells which framing layer to write next among the four root blueprints.</li></ol><h3 id="move-through-the-phases" tabindex="-1">Move through the phases <a class="header-anchor" href="#move-through-the-phases" aria-label="Permalink to &quot;Move through the phases&quot;">​</a></h3><p>An OPALE story goes through five phases: <code>O-analyse</code>, <code>P-cadrage</code>, <code>A-specs</code>, <code>L-plan</code>, <code>E-execute</code>.</p><ol><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#phase-eligibility"><code>effortless_phase_eligibility</code></a>: read-only. Tells whether the current phase&#39;s required documents exist and which phase comes next.</li><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#phase-next"><code>effortless_phase_next</code></a>: moves to the next phase, with the date set by the server. The engine redoes the check on its side.</li><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#story-reloop"><code>effortless_story_reloop</code></a>, when the framing has to be redone: <code>target_phase</code> names a phase earlier than the current one.</li></ol><p>As long as the story is before the <code>E-execute</code> phase, a task cannot move to <strong>In progress</strong> (see <a href="/Effortless/en/agent/piloter.html">Run the work</a>).</p><h3 id="record-decisions" tabindex="-1">Record decisions <a class="header-anchor" href="#record-decisions" aria-label="Permalink to &quot;Record decisions&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/cadrage.html#decision-add"><code>effortless_decision_add</code></a>: a decision (ADR) attached to a story. The agent fills in <code>epic_id</code>, <code>story_id</code>, <code>title</code>, <code>context</code>, <code>decision</code>, <code>consequences</code>, <code>rejected_alternatives</code> and the OPALE <code>phase</code> concerned. The engine returns the <code>DEC-NN</code> identifier.</li><li><a href="/Effortless/en/reference/mcp/cadrage.html#decisions-list"><code>effortless_decisions_list</code></a>: all the project&#39;s decisions, with their epic and story of origin.</li></ol><h3 id="ask-and-resolve-questions" tabindex="-1">Ask and resolve questions <a class="header-anchor" href="#ask-and-resolve-questions" aria-label="Permalink to &quot;Ask and resolve questions&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/cadrage.html#question-ask"><code>effortless_question_ask</code></a>: an open question on a story (<code>question</code>, <code>context</code>, <code>impact</code>, <code>suggestion</code>, <code>phase</code>). The engine returns <code>Q-NN</code>.</li><li><a href="/Effortless/en/reference/mcp/cadrage.html#question-resolve"><code>effortless_question_resolve</code></a>: resolves it with its <code>answer</code>.</li><li><a href="/Effortless/en/reference/mcp/cadrage.html#questions-list"><code>effortless_questions_list</code></a>: all the project&#39;s questions.</li></ol><h3 id="big-open-questions-bqo" tabindex="-1">Big open questions (BQO) <a class="header-anchor" href="#big-open-questions-bqo" aria-label="Permalink to &quot;Big open questions (BQO)&quot;">​</a></h3><p>A BQO is a question asked at project level, not on a story.</p><ol><li><a href="/Effortless/en/reference/mcp/cadrage.html#bqo-ask"><code>effortless_bqo_ask</code></a>: records it.</li><li><a href="/Effortless/en/reference/mcp/cadrage.html#bqo-list"><code>effortless_bqo_list</code></a>: lists them.</li><li><a href="/Effortless/en/reference/mcp/cadrage.html#bqo-resolve"><code>effortless_bqo_resolve</code></a>: answers it (<code>question_id</code>, <code>answer</code>).</li><li><a href="/Effortless/en/reference/mcp/cadrage.html#bqo-graduate"><code>effortless_bqo_graduate</code></a>: if it deserves a project of its own, copies it into an <strong>existing</strong> epic (<code>epic_id</code>). It does not create an epic; the question is no longer answered at project level but from that epic.</li></ol><h3 id="story-drafts" tabindex="-1">Story drafts <a class="header-anchor" href="#story-drafts" aria-label="Permalink to &quot;Story drafts&quot;">​</a></h3><p>To break an epic down without creating the stories right away.</p><ol><li><a href="/Effortless/en/reference/mcp/cadrage.html#draft-add"><code>effortless_draft_add</code></a>: a draft (title, summary, <code>kind</code> <code>opale</code> or <code>fix</code>, proposed tasks, rationale, dependencies) in the active epic or the named one.</li><li><a href="/Effortless/en/reference/mcp/cadrage.html#draft-update"><code>effortless_draft_update</code></a>: edits a draft; anything not passed stays unchanged.</li><li><a href="/Effortless/en/reference/mcp/cadrage.html#draft-list"><code>effortless_draft_list</code></a>: lists an epic&#39;s drafts.</li><li><a href="/Effortless/en/reference/mcp/cadrage.html#draft-submit"><code>effortless_draft_submit</code></a>: submits it for your review.</li><li><a href="/Effortless/en/reference/mcp/cadrage.html#draft-validate"><code>effortless_draft_validate</code></a>: turns it into a real story and returns the identifier created.</li><li><a href="/Effortless/en/reference/mcp/cadrage.html#draft-reject"><code>effortless_draft_reject</code></a>: sets it aside.</li></ol><p>The agent submits; you are the one who says validate or reject.</p><h3 id="proposals-on-a-story" tabindex="-1">Proposals on a story <a class="header-anchor" href="#proposals-on-a-story" aria-label="Permalink to &quot;Proposals on a story&quot;">​</a></h3><p>A proposal is a summary attached to a story, waiting for your verdict.</p><ol><li><a href="/Effortless/en/reference/mcp/cadrage.html#proposal-add"><code>effortless_proposal_add</code></a>: adds it (pending) to the active story, or to <code>story_id</code>.</li><li><a href="/Effortless/en/reference/mcp/cadrage.html#proposal-validate"><code>effortless_proposal_validate</code></a>: validates it.</li><li><a href="/Effortless/en/reference/mcp/cadrage.html#proposal-reject"><code>effortless_proposal_reject</code></a>: rejects it.</li></ol><h3 id="the-short-route-a-fix" tabindex="-1">The short route: a fix <a class="header-anchor" href="#the-short-route-a-fix" aria-label="Permalink to &quot;The short route: a fix&quot;">​</a></h3><p>For a defect to fix right now, the agent does not need to frame anything.</p><ol><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#story-start"><code>effortless_story_start</code></a> with <code>kind: &quot;fix&quot;</code>: the story needs no framing and opens directly in the execution phase. With <code>activate: true</code>, it becomes the active story.</li><li><a href="/Effortless/en/reference/mcp/cycle-de-vie.html#task-add"><code>effortless_task_add</code></a> then <a href="/Effortless/en/reference/mcp/cycle-de-vie.html#task-update"><code>effortless_task_update</code></a>: the rest goes as for a normal story (<a href="/Effortless/en/agent/piloter.html">Run the work</a>).</li></ol><h3 id="acceptance-scenarios-and-proofs" tabindex="-1">Acceptance scenarios and proofs <a class="header-anchor" href="#acceptance-scenarios-and-proofs" aria-label="Permalink to &quot;Acceptance scenarios and proofs&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/cadrage.html#recipe-maturity"><code>effortless_recipe_maturity</code></a>: read-only. Sorts the acceptance scenarios by maturity (stable, candidate, beta, planned), returns what remains to be done and the scenarios blocked by a gap. Optionally limited to one <code>epic_id</code> or <code>story_id</code>.</li><li><a href="/Effortless/en/reference/mcp/cadrage.html#interruption-proof"><code>effortless_interruption_proof</code></a>: proves that a write order survives a real interruption. The engine kills the declared command (SIGKILL) at each position it announces, then runs the state check. <code>proof_id</code> names a proof you declared in <code>effortless.json</code> under <code>settings.interruption_proofs</code>; <code>positions</code> restricts the cuts (by default, all of them).</li></ol><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><ul><li>Framing documents in <code>blueprints/</code>, in Markdown, to read in your editor.</li><li>Decisions and questions in the <a href="/Effortless/en/guide/knowledge.html">Knowledge</a> screen, with their origin.</li><li>Stories, their phase and their drafts in the <a href="/Effortless/en/guide/backlog.html">Backlog</a> (the <strong>Drafts</strong>, <strong>Proposal</strong> and <strong>Reloop</strong> blocks on the epic and story pages).</li><li>Open questions and unverified acceptance scenarios under <strong>Waiting for you</strong> on the <a href="/Effortless/en/guide/dashboard.html">Dashboard</a>.</li></ul><h2 id="when-the-agent-is-refused" tabindex="-1">When the agent is refused <a class="header-anchor" href="#when-the-agent-is-refused" aria-label="Permalink to &quot;When the agent is refused&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>What the refusal says</th><th>What to do</th></tr></thead><tbody><tr><td>A task moves to <strong>In progress</strong> while the story&#39;s framing is unfinished</td><td><code>cadrage:phaseIncomplete</code></td><td>Provide the phase&#39;s missing documents, or open a direct fix with <code>story_start</code> and <code>kind: &quot;fix&quot;</code>.</td></tr><tr><td>Moving to the next phase, required documents missing</td><td><code>pilotage:phaseMissingDocs</code></td><td>Write the documents the refusal names.</td></tr><tr><td>Moving to the next phase while the story is already in the last phase</td><td><code>pilotage:phaseAlreadyLast</code></td><td>Nothing to lift: close the story, or reloop it to an earlier phase.</td></tr><tr><td>Phase already completed</td><td><code>pilotage:phaseAlreadyCompleted</code></td><td>Move to the next phase, or go back with <code>story_reloop</code>.</td></tr><tr><td>A decision with an escaped HTML entity in a field (for example <code>&amp;amp;</code>)</td><td><code>cadrage:entiteHtml</code></td><td>Rewrite the field without the entity.</td></tr><tr><td>Resolving at project level a BQO already graduated into an epic</td><td><code>cadrage:questionGraduated</code></td><td>Answer from the BQOs of the epic that holds it, with <code>question_resolve</code>.</td></tr><tr><td>Unknown BQO</td><td><code>cadrage:questionNotFound</code></td><td>List the BQOs with <code>bqo_list</code> and use the right identifier.</td></tr><tr><td>Reading a story&#39;s items without naming the epic and the story</td><td><code>pilotage:noStoryTarget</code></td><td>Pass <code>epic_id</code> AND <code>story_id</code>; <code>project_tree</code> names them.</td></tr><tr><td>Interruption proof not declared</td><td><code>proof:unknown</code></td><td>Declare it in <code>settings.interruption_proofs</code> of <code>effortless.json</code>.</td></tr><tr><td>Proof whose command announces no position</td><td><code>proof:noPosition</code></td><td>Have the command write <code>EFFORTLESS-POS &lt;n&gt;</code> at each cut point.</td></tr><tr><td>Proof whose command cannot be launched</td><td><code>proof:launchFailed</code></td><td>Check the declared command.</td></tr></tbody></table>',30))])}const b=s(l,[["render",h]]);export{_ as __pageData,b as default};
